function autotile(grid, x, y) {
  const wall = (cx, cy) => (grid[cy] || "")[cx] === "#";
  let mask = 0;
  if (wall(x, y - 1)) mask |= 1;
  if (wall(x + 1, y)) mask |= 2;
  if (wall(x, y + 1)) mask |= 4;
  if (wall(x - 1, y)) mask |= 8;
  return mask;
}

