stages.s:
const POISON = 1, BURN = 2, FREEZE = 4, STUN = 8;
const BIT = { POISON, BURN, FREEZE, STUN };
function takeTurn(status, events) {
  for (const ev of events) {
    const [action, name] = ev.split(" ");
    if (action === "add") status |= BIT[name];
    else if (action === "remove") status &= ~BIT[name];
    else if (action === "toggle") status ^= BIT[name];
    else if (action === "cure") status = 0;
  }
  let damage = 0;
  if (status & POISON) damage += 2;
  if (status & BURN) damage += 3;
  const canAct = (status & (FREEZE | STUN)) === 0;
  return { status, damage, canAct };
}

